+function interact(){if(state!=='playing')return;let near=loot.filter(l=>!l.taken&&distance(l,player)<58).sort((a,b)=>distance(a,player)-distance(b,player))[0];if(near){near.taken=true;if(near.type==='med'){meds=Math.min(meds+1,4);toast('MEDKIT SECURED')}else{pack+=near.value;toast('SALVAGE SECURED  +'+near.value+' CR')}updateHUD();return}if(distance(player,extract)<90){if(!extract.active){extract.active=true;extractTime=12;$('goal').textContent='Hold position. Uplink active.';$('goalSub').textContent='Stay inside the signal ring for 12 seconds.';toast('UPLINK ACTIVATED // HOLD THE LINE')}else toast('SIGNAL LOCKED // '+Math.ceil(extractTime)+' SEC');return}toast('NOTHING IN REACH')}
