+function damage(amount){if(player.iframes>0)return;health-=amount;player.iframes=.65;for(let i=0;i<7;i++)particles.push({x:player.x,y:player.y,vx:(Math.random()-.5)*120,vy:(Math.random()-.5)*120,life:.35,color:'#e46c59'});if(health<=0){health=0;finish(false)}updateHUD()}
+function finish(success){if(state!=='playing')return;state='result';$('hud').classList.remove('active');$('mobile').style.display='none';let secured=success?pack:0;if(success){stash+=secured;localStorage.setItem('dustlineStash',stash);$('resultEyebrow').textContent='SIGNAL ACQUIRED';$('resultTitle').textContent='Extracted';$('resultText').textContent='You made it back to the safehouse. The yard can keep its ghosts.';$('resultValue').textContent='+ '+secured+' CR SECURED  //  RESERVE '+stash+' CR';}else{$('resultEyebrow').textContent='SIGNAL LOST';$('resultTitle').textContent='Operator down';$('resultText').textContent='Your pack was left behind in the quiet yard. Regroup and try another route.';$('resultValue').textContent='− '+pack+' CR LOST  //  RESERVE '+stash+' CR';}$('resultButton').textContent='Return to safehouse';$('resultModal').classList.add('show')}

