function update(dt){if(state!=='playing')return;elapsed+=dt;fireCooldown=Math.max(0,fireCooldown-dt);reload=Math.max(0,reload-dt);player.iframes=Math.max(0,player.iframes-dt);recoil=Math.max(0,recoil-dt);if(reload===0&&ammo<12&&reserve>0){let take=Math.min(12-ammo,reserve);ammo+=take;reserve-=take;if(take)updateHUD()}
let dx=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),dy=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0);if(stickVector.x||stickVector.y){dx=stickVector.x;dy=stickVector.y}let mag=Math.hypot(dx,dy);if(mag){dx/=Math.max(1,mag);dy/=Math.max(1,mag)}moveBody(player,dx*player.speed*dt,dy*player.speed*dt,player.r);
cam.x=clamp(player.x-W/2,0,world.w-W);cam.y=clamp(player.y-H/2,0,world.h-H);if(world.w<W)cam.x=(world.w-W)/2;if(world.h<H)cam.y=(world.h-H)/2;
if(!isMobile())player.angle=Math.atan2(mouse.y-(player.y-cam.y),mouse.x-(player.x-cam.x));else{let target=enemies.filter(e=>!e.dead).sort((a,b)=>distance(a,player)-distance(b,player))[0];if(target)player.angle=Math.atan2(target.y-player.y,target.x-player.x)}if(mouse.down||touchFiring)fire();
for(const s of shots){s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;if(obstacles.some(o=>s.x>o.x&&s.x<o.x+o.w&&s.y>o.y&&s.y<o.y+o.h))s.life=0;for(const e of enemies){if(!e.dead&&Math.hypot(s.x-e.x,s.y-e.y)<e.r+4){e.hp--;s.life=0;for(let i=0;i<5;i++)particles.push({x:e.x,y:e.y,vx:(Math.random()-.5)*95,vy:(Math.random()-.5)*95,life:.25,color:'#e6ae6b'});if(e.hp<=0){e.dead=true;pack+=15;toast('SENTRY DOWN  +15 CR');updateHUD()}break}}}shots=shots.filter(s=>s.life>0);
for(const e of enemies){if(e.dead)continue;let d=distance(e,player);if(d<470)e.alert=Math.max(e.alert,2);else e.alert=Math.max(0,e.alert-dt);if(e.alert>0){e.angle=Math.atan2(player.y-e.y,player.x-e.x);if(d>145){let vx=Math.cos(e.angle)*e.speed*dt,vy=Math.sin(e.angle)*e.speed*dt;moveBody(e,vx,vy,e.r);if(blocked(e.x+vx,e.y+vy,e.r)){moveBody(e,Math.cos(e.angle+1.15)*e.speed*dt,Math.sin(e.angle+1.15)*e.speed*dt,e.r)}}e.shoot-=dt;if(d<470&&e.shoot<=0){e.shoot=1.5+Math.random()*1.1;let a=e.angle+(Math.random()-.5)*.11;hostileShots.push({x:e.x+Math.cos(a)*17,y:e.y+Math.sin(a)*17,vx:Math.cos(a)*310,vy:Math.sin(a)*310,life:1.6})}}}
for(const s of hostileShots){s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;if(obstacles.some(o=>s.x>o.x&&s.x<o.x+o.w&&s.y>o.y&&s.y<o.y+o.h))s.life=0;if(Math.hypot(s.x-player.x,s.y-player.y)<player.r+4){s.life=0;damage(9)}}hostileShots=hostileShots.filter(s=>s.life>0);
