// sun-baked concrete with orderly seams
ctx.fillStyle='#34392f';ctx.fillRect(0,0,world.w,world.h);ctx.strokeStyle='rgba(190,183,146,.045)';ctx.lineWidth=1;for(let x=0;x<=world.w;x+=120){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,world.h);ctx.stroke()}for(let y=0;y<=world.h;y+=120){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(world.w,y);ctx.stroke()}
// road lanes
ctx.fillStyle='#292f29';ctx.fillRect(0,825,world.w,165);ctx.fillStyle='rgba(199,180,118,.2)';for(let x=10;x<world.w;x+=95)ctx.fillRect(x,905,47,3);
for(const d of decor){ctx.save();ctx.translate(d.x,d.y);ctx.rotate(d.rot);if(d.type==='scrub'){ctx.fillStyle='#42483a';ctx.beginPath();ctx.ellipse(0,0,d.r*1.35,d.r*.8,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#596047';ctx.beginPath();ctx.arc(-4,-2,d.r*.55,0,6.28);ctx.fill()}else{ctx.fillStyle='#494b42';ctx.beginPath();ctx.moveTo(-d.r,-2);ctx.lineTo(-d.r*.35,-d.r*.8);ctx.lineTo(d.r*.7,-d.r*.5);ctx.lineTo(d.r,4);ctx.lineTo(0,d.r*.6);ctx.closePath();ctx.fill()}ctx.restore()}
// distant boundary and wrecked perimeter fence
ctx.strokeStyle='#747660';ctx.lineWidth=9;ctx.strokeRect(16,16,world.w-32,world.h-32);ctx.strokeStyle='rgba(181,182,151,.27)';ctx.lineWidth=2;ctx.strokeRect(30,30,world.w-60,world.h-60);for(let x=60;x<world.w;x+=100){ctx.fillStyle='#787967';ctx.fillRect(x,12,4,14);ctx.fillRect(x,world.h-26,4,14)}
for(const o of obstacles)drawObstacle(o);
// extraction pad and beacon
let pulse=.5+.5*Math.sin(elapsed*3);ctx.save();ctx.translate(extract.x,extract.y);ctx.fillStyle='rgba(12,18,16,.55)';ctx.beginPath();ctx.arc(0,0,extract.r+18,0,Math.PI*2);ctx.fill();ctx.strokeStyle=extract.active?'rgba(130,236,177,.8)':'rgba(224,167,78,.62)';ctx.lineWidth=2;ctx.setLineDash([9,8]);ctx.beginPath();ctx.arc(0,0,extract.r+5+pulse*5,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=extract.active?'#9ce0b1':'#d7a24f';ctx.beginPath();ctx.arc(0,0,18,0,Math.PI*2);ctx.fill();ctx.fillStyle='#222820';ctx.beginPath();ctx.moveTo(-7,4);ctx.lineTo(0,-8);ctx.lineTo(7,4);ctx.closePath();ctx.fill();ctx.fillStyle='#e2d9bd';ctx.font='700 11px ui-monospace';ctx.textAlign='center';ctx.fillText(extract.active?'UPLINK':'EXTRACT',0,extract.r+24);if(extract.active){ctx.strokeStyle='rgba(145,232,175,.17)';ctx.lineWidth=5;ctx.beginPath();ctx.arc(0,0,extract.r, -Math.PI/2,-Math.PI/2+(1-extractTime/12)*Math.PI*2);ctx.stroke()}ctx.restore();
for(const l of loot){if(l.taken)continue;let bob=Math.sin(elapsed*3+l.x)*2;ctx.save();ctx.translate(l.x,l.y+bob);ctx.fillStyle='rgba(8,10,9,.5)';ctx.beginPath();ctx.ellipse(0,8,12,5,0,0,6.28);ctx.fill();ctx.fillStyle=l.type==='med'?'#9acbb0':'#d0a352';ctx.fillRect(-8,-7,16,14);ctx.strokeStyle='#26271e';ctx.lineWidth=2;ctx.strokeRect(-5,-4,10,8);ctx.fillStyle='#f0d8a4';ctx.fillRect(-2,-4,4,8);ctx.restore()}
for(const e of enemies)if(!e.dead)drawEnemy(e);
for(const s of shots){ctx.strokeStyle='#f5d38b';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(s.x,s.y);ctx.lineTo(s.x-s.vx*.025,s.y-s.vy*.025);ctx.stroke()}for(const s of hostileShots){ctx.fillStyle='#ec765e';ctx.beginPath();ctx.arc(s.x,s.y,4,0,6.28);ctx.fill();ctx.fillStyle='#f5a086';ctx.beginPath();ctx.arc(s.x,s.y,1.5,0,6.28);ctx.fill()}
for(const p of particles){ctx.globalAlpha=Math.min(1,p.life*4);ctx.fillStyle=p.color;ctx.fillRect(p.x-2,p.y-2,4,4)}ctx.globalAlpha=1;
drawPlayer();ctx.restore();drawOverlay();requestAnimationFrame(draw)}

